def rabinowitz_eval(c: int, x: int) -> int:
    return x * x + x + c

def prime_streak(c: int) -> int:
    x = 0
    while is_prime(rabinowitz_eval(c, x)):
        x += 1
    return x

def is_qnr(d: int, p: int) -> bool:
    qr = {(x * x) % p for x in range(p)}
    return (-d % p) not in qr

def form_representations(n: int, c: int = 41, bound: int = 100):
    reps = []
    for y in range(-bound, bound + 1):
        for x in range(-bound, bound + 1):
            if x*x + x*y + c*y*y == n:
                reps.append((x, y))
    return reps
